456→#[cfg(test)]
457→mod tests {
458→    use super::*;
459→    use crate::ui::MockUI;
460→    use tempfile::TempDir;
461→
462→    fn create_test_store(temp: &TempDir) -> FeedbackStore {
463→        FeedbackStore::new(temp.path().join("feedback.jsonl"))
464→    }
465→
466→    #[test]
467→    fn list_empty_feedback() {
468→        let temp = TempDir::new().unwrap();
469→        let store = create_test_store(&temp);
470→        let mut ui = MockUI::new();
471→
472→        let result = list_feedback(&store, None, None, false, &mut ui).unwrap();
473→        assert_eq!(result, 0);
474→    }
475→
476→    #[test]
477→    fn list_feedback_with_entries() {
478→        let temp = TempDir::new().unwrap();
479→        let store = create_test_store(&temp);
480→        let mut ui = MockUI::new();
481→
482→        store.append(&FeedbackEntry::new("test issue")).unwrap();
483→
484→        let result = list_feedback(&store, None, None, false, &mut ui).unwrap();
485→        assert_eq!(result, 0);
486→    }
487→
488→    #[test]
489→    fn capture_feedback_basic() {
490→        let temp = TempDir::new().unwrap();
491→        let store = create_test_store(&temp);
492→        let mut ui = MockUI::new();
493→
494→        let result = capture_feedback(
495→            &store,
496→            "test feedback",
497→            "other",
498→            vec![],
499→            None,
500→            true,
501→            &mut ui,
502→        )
503→        .unwrap();
504→
505→        assert_eq!(result, 0);
506→
